module phone_numbers(\n    input [6:0] n,\n    input [399:0] digits,\n    output reg [3:0] result\n);\n    reg [3:0] k;\n    reg [6:0] count_8;\n    integer i;\n    always @(*) begin\n        if (n >= 7'd99) k = 4'd9;\n        else if (n >= 7'd88) k = 4'd8;\n        else if (n >= 7'd77) k = 4'd7;\n        else if (n >= 7'd66) k = 4'd6;\n        else if (n >= 7'd55) k = 4'd5;\n        else if (n >= 7'd44) k = 4'd4;\n        else if (n >= 7'd33) k = 4'd3;\n        else if (n >= 7'd22) k = 4'd2;\n        else if (n >= 7'd11) k = 4'd1;\n        else k = 4'd0;\n        count_8 = 7'd0;\n        for (i = 0; i < 100; i = i + 1) begin\n            if (i < n) begin\n                if (digits[399 - (i * 4) -:4] == 4'd8) begin\n                    count_8 = count_8 + 1;\n                end\n            end\n        end\n        result = (count_8 < k) ? count_8[3:0] : k;\n    end\nendmodule